begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_table('public','consultation_receipts','durable message decision');
select has_function('public','claim_consultation_job',array['uuid','uuid'],'dedicated serialized claim');
select public.ingest_facebook_events('a0000000-0000-0000-0000-000000000001','10000000017','[
 {"pageId":"10000000017","providerKey":"message:ov017-a","kind":"message","senderId":"20000000017","recipientId":"10000000017","data":{"text":"Tư vấn máy"}},
 {"pageId":"10000000017","providerKey":"message:ov017-b","kind":"message","senderId":"20000000017","recipientId":"10000000017","data":{"text":"Gặp nhân viên"}}
]');
create temporary table claim1 as select public.claim_consultation_job('d1700000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000001') value;
select ok((select value is not null from claim1),'claims a durable private input');
select is(public.claim_consultation_job('d1700000-0000-0000-0000-000000000002','a0000000-0000-0000-0000-000000000001'),null::jsonb,'second worker cannot overlap a conversation');
select ok(not has_table_privilege('authenticated','public.consultation_receipts','select'),'private receipt is service only');
select ok(not has_function_privilege('authenticated','public.claim_consultation_job(uuid,uuid)','execute'),'browser cannot claim');
select ok(not exists(select 1 from public.claim_business_job('d1700000-0000-0000-0000-000000000009') b join public.facebook_inbound_events e on e.id=b.entity_id where e.page_id='10000000017'),'generic claimant cannot steal private ingress');
select ok(not public.finish_consultation((value#>>'{job,id}')::uuid,(value#>>'{job,lease_owner}')::uuid,'d1700000-0000-0000-0000-000000000009','{"type":"reply","intent":"praise","text":"Cảm ơn","claims":[]}'),'wrong lease token cannot finish') from claim1;
select ok(public.finish_consultation((value#>>'{job,id}')::uuid,(value#>>'{job,lease_owner}')::uuid,(value#>>'{job,lease_token}')::uuid,'{"type":"reply","intent":"praise","text":"Cảm ơn","claims":[]}'),'valid reply is committed') from claim1;
select ok(public.finish_consultation((value#>>'{job,id}')::uuid,(value#>>'{job,lease_owner}')::uuid,(value#>>'{job,lease_token}')::uuid,'{"type":"reply","intent":"praise","text":"Cảm ơn","claims":[]}'),'finish replay is successful without duplicate outcome') from claim1;
select is((select count(*) from public.consultation_receipts where status='completed' and conversation_id=(select (value->>'conversationId')::uuid from claim1)),1::bigint,'one immutable receipt');
create temporary table claim2 as select public.claim_consultation_job('d1700000-0000-0000-0000-000000000002','a0000000-0000-0000-0000-000000000001') value;
select ok(public.finish_consultation((value#>>'{job,id}')::uuid,(value#>>'{job,lease_owner}')::uuid,(value#>>'{job,lease_token}')::uuid,'{"type":"handoff","intent":"handoff","reason":"customer_requested"}'),'handoff and acknowledgment commit together') from claim2;
select is((select candidate->>'type' from public.consultation_receipts where event_id=(select (value#>>'{job,entity_id}')::uuid from claim2)),'handoff_ack','one exceptional acknowledgment candidate');
select is((select status from public.conversations where id=(select (value->>'conversationId')::uuid from claim1)),'WAITING_STAFF','receipt handoff pauses conversation');
select is((select count(*) from public.business_jobs where kind='outbound_message' and organization_id='a0000000-0000-0000-0000-000000000001'),0::bigint,'no sends or outbound job created');
select public.ingest_facebook_events('a0000000-0000-0000-0000-000000000001','10000000018','[{"pageId":"10000000018","providerKey":"message:old-projected","kind":"message","senderId":"20000000018","recipientId":"10000000018","data":{"text":"old projection only"}}]');
update public.business_jobs set status='succeeded' where entity_id=(select id from public.facebook_inbound_events where provider_key='message:old-projected' and page_id='10000000018');
create temporary table recovered as select public.claim_consultation_job('d1700000-0000-0000-0000-000000000003','a0000000-0000-0000-0000-000000000001') value;
select is((select value->>'text' from recovered),'old projection only','succeeded projection-only job is recovered');
update public.business_jobs set lease_expires_at=clock_timestamp()-interval '1 second' where id=(select (value#>>'{job,id}')::uuid from recovered);
create temporary table reclaimed as select public.claim_consultation_job('d1700000-0000-0000-0000-000000000004','a0000000-0000-0000-0000-000000000001') value;
select isnt((select value#>>'{job,lease_token}' from recovered),(select value#>>'{job,lease_token}' from reclaimed),'crash reclaim changes fencing token');
select ok(not public.finish_consultation((value#>>'{job,id}')::uuid,(value#>>'{job,lease_owner}')::uuid,(value#>>'{job,lease_token}')::uuid,'{"type":"reply","intent":"praise","text":"late reply","claims":[]}'),'stale worker cannot persist') from recovered;
select public.request_conversation_handoff('a0000000-0000-0000-0000-000000000001',(value#>>'{job,entity_id}')::uuid,(value->>'revision')::integer,'customer_requested') from reclaimed;
select ok(public.finish_consultation((value#>>'{job,id}')::uuid,(value#>>'{job,lease_owner}')::uuid,(value#>>'{job,lease_token}')::uuid,'{"type":"reply","intent":"praise","text":"late reply","claims":[]}'),'pause during generation produces terminal suppressed receipt') from reclaimed;
select is((select outcome->>'type' from public.consultation_receipts where event_id=(select (value#>>'{job,entity_id}')::uuid from reclaimed)),'suppressed','paused candidate withheld');
select public.ingest_facebook_events('a0000000-0000-0000-0000-000000000001','10000000019','[{"pageId":"10000000019","providerKey":"message:exhausted","kind":"message","senderId":"20000000019","recipientId":"10000000019","data":{"text":"worker crashed repeatedly"}},{"pageId":"10000000019","providerKey":"message:invalid","kind":"message","senderId":"10000000019","recipientId":"10000000019","data":{"text":"self sender"}}]');
update public.business_jobs set attempts=3 where entity_id in(select id from public.facebook_inbound_events where page_id='10000000019');
select is(public.claim_consultation_job('d1700000-0000-0000-0000-000000000005','a0000000-0000-0000-0000-000000000001'),null::jsonb,'exhausted/invalid events reconcile without AI');
select is((select outcome->>'type' from public.consultation_receipts where event_id=(select id from public.facebook_inbound_events where page_id='10000000019' and provider_key='message:exhausted')),'gap','exhaustion records knowledge gap rather than abandonment');
select is((select candidate->>'type' from public.consultation_receipts where event_id=(select id from public.facebook_inbound_events where page_id='10000000019' and provider_key='message:exhausted')),'handoff_ack','exhaustion has one durable staff acknowledgment');
select is((select outcome->>'type' from public.consultation_receipts where event_id=(select id from public.facebook_inbound_events where page_id='10000000019' and provider_key='message:invalid')),'ignored','invalid identity cannot poison queue');
insert into public.products(id,organization_id,source_url,canonical_url,name,sku,price_vnd,in_stock,stock_quantity,quality) values('d1700000-0000-0000-0000-000000000017','a0000000-0000-0000-0000-000000000001','https://fixture.example/ov017','https://fixture.example/ov017','Original name','ORIGINAL',500,true,2,'usable');
select public.ingest_facebook_events('a0000000-0000-0000-0000-000000000001','10000000020','[{"pageId":"10000000020","providerKey":"message:changed-fact","kind":"message","senderId":"20000000020","recipientId":"10000000020","data":{"text":"Giá bao nhiêu"}}]');
create temporary table changed_claim as select public.claim_consultation_job('d1700000-0000-0000-0000-000000000006','a0000000-0000-0000-0000-000000000001') value;
update public.products set name='Changed name' where id='d1700000-0000-0000-0000-000000000017';
select ok(public.finish_consultation((value#>>'{job,id}')::uuid,(value#>>'{job,lease_owner}')::uuid,(value#>>'{job,lease_token}')::uuid,'{"type":"reply","intent":"needs","text":"Original name giá 500 đồng","claims":[{"kind":"catalog","productId":"d1700000-0000-0000-0000-000000000017","variantId":null,"version":1,"variantUpdatedAt":null,"name":"Original name","sku":"ORIGINAL","field":"price_vnd","value":500}]}'),'changed rendered identity is reconciled') from changed_claim;
select is((select outcome->>'type' from public.consultation_receipts where event_id=(select (value#>>'{job,entity_id}')::uuid from changed_claim)),'gap','same-version name change cannot produce stale labeled price');
select throws_ok($$update public.consultation_receipts set outcome='{}' where event_id=(select (value#>>'{job,entity_id}')::uuid from changed_claim)$$,'P0001','immutable_consultation_receipt','terminal outcomes cannot be rewritten');
select public.ingest_facebook_events('a0000000-0000-0000-0000-000000000001','10000000021','[{"pageId":"10000000021","providerKey":"message:atomic","kind":"message","senderId":"20000000021","recipientId":"10000000021","data":{"text":"Gặp nhân viên"}}]');
create temporary table atomic_claim as select public.claim_consultation_job('d1700000-0000-0000-0000-000000000007','a0000000-0000-0000-0000-000000000001') value;
create function pg_temp.reject_consultation_audit() returns trigger language plpgsql as $$begin if new.action='consultation.completed' then raise exception 'fixture_audit_failure';end if;return new;end $$;
create trigger fixture_consultation_audit before insert on public.audit_events for each row execute function pg_temp.reject_consultation_audit();
select throws_ok($$select public.finish_consultation((value#>>'{job,id}')::uuid,(value#>>'{job,lease_owner}')::uuid,(value#>>'{job,lease_token}')::uuid,'{"type":"handoff","intent":"handoff","reason":"customer_requested"}') from atomic_claim$$,'P0001','fixture_audit_failure','audit failure rolls back entire handoff and receipt');
select is((select status from public.conversations where id=(select (value->>'conversationId')::uuid from atomic_claim)),'AI_ACTIVE','failed finish did not pause without a receipt');
select is((select status from public.consultation_receipts where event_id=(select (value#>>'{job,entity_id}')::uuid from atomic_claim)),'running','failed finish remains resumable');
drop trigger fixture_consultation_audit on public.audit_events;
select public.finish_consultation((value#>>'{job,id}')::uuid,(value#>>'{job,lease_owner}')::uuid,(value#>>'{job,lease_token}')::uuid,'{"type":"route","intent":"checkout","route":"checkout"}') from atomic_claim;
insert into public.knowledge_sources(id,organization_id,version,document) values('d1700000-0000-0000-0000-000000000050','a0000000-0000-0000-0000-000000000001',1,'{"name":"Technical guide","kind":"text","text":"RAM 16GB hỗ trợ công việc văn phòng.","url":null,"authority":"reference","productIds":["d1700000-0000-0000-0000-000000000017"],"topics":[],"freshnessHours":1,"active":true}');
insert into public.knowledge_ingestion_runs(id,organization_id,source_id,source_version,refresh_cycle) values('d1700000-0000-0000-0000-000000000051','a0000000-0000-0000-0000-000000000001','d1700000-0000-0000-0000-000000000050',1,1);
insert into public.knowledge_ingestions(id,organization_id,source_id,source_version,source_document,content_hash,content_type,fetched_at,expires_at) select 'd1700000-0000-0000-0000-000000000051',organization_id,id,1,document,repeat('a',64),'text/plain',clock_timestamp(),clock_timestamp()+interval '1 hour' from public.knowledge_sources where id='d1700000-0000-0000-0000-000000000050';
insert into public.knowledge_chunks(ingestion_id,ordinal,body) values('d1700000-0000-0000-0000-000000000051',1,'RAM 16GB hỗ trợ công việc văn phòng.');
select public.ingest_facebook_events('a0000000-0000-0000-0000-000000000001','10000000022','[{"pageId":"10000000022","providerKey":"message:source-conflict","kind":"message","senderId":"20000000022","recipientId":"10000000022","data":{"text":"Mô tả RAM"}}]');
create temporary table source_claim as select public.claim_consultation_job('d1700000-0000-0000-0000-000000000008','a0000000-0000-0000-0000-000000000001') value;
create temporary table source_outcome as select jsonb_build_object('type','reply','intent','needs','text','Theo tài liệu: RAM 16GB hỗ trợ công việc văn phòng.','claims',jsonb_build_array(public.read_current_knowledge('a0000000-0000-0000-0000-000000000001','d1700000-0000-0000-0000-000000000050')||'{"kind":"knowledge","productId":"d1700000-0000-0000-0000-000000000017","value":"RAM 16GB hỗ trợ công việc văn phòng.","canonicalSpecs":[{"kind":"catalog_snapshot","productId":"d1700000-0000-0000-0000-000000000017","variantId":null,"version":1,"variantUpdatedAt":null,"specs":{}}]}'::jsonb)) value;
update public.products set specifications='[{"name":"RAM","value":"32GB"}]' where id='d1700000-0000-0000-0000-000000000017';
select ok(public.finish_consultation((value#>>'{job,id}')::uuid,(value#>>'{job,lease_owner}')::uuid,(value#>>'{job,lease_token}')::uuid,(select value from source_outcome)),'source quote rechecks even previously absent canonical specs') from source_claim;
select is((select outcome->>'type' from public.consultation_receipts where event_id=(select (value#>>'{job,entity_id}')::uuid from source_claim)),'gap','new catalog contradiction fences source-only reply');
select * from finish();
rollback;
